/**
 * @file The descriptors of the protobuf messages of the SDK (loaded from src/bosdyn/descriptor_set.pb), used by the
 * text and JSON formats, and mergeFrom(), like MergeFrom() in Python.
 */

'use strict';

/**
 * Descriptors of the protobuf messages of the SDK, like the default descriptor pool of the Python protobuf package.
 *
 * The code generated by protoc-gen-js has no descriptors: they are read from src/bosdyn/descriptor_set.pb, a
 * FileDescriptorSet generated by build.js from the same .proto files as the code. The jspb accessors of a field are
 * named from the name of the field like protoc-gen-js does.
 */

const { readFileSync } = require('node:fs');
const path = require('node:path');

const DESCRIPTOR_SET_PATH = path.join(__dirname, '..', 'bosdyn', 'descriptor_set.pb');

/** The types of FieldDescriptorProto.Type. */
const FieldType = Object.freeze({
  DOUBLE: 1,
  FLOAT: 2,
  INT64: 3,
  UINT64: 4,
  INT32: 5,
  FIXED64: 6,
  FIXED32: 7,
  BOOL: 8,
  STRING: 9,
  GROUP: 10,
  MESSAGE: 11,
  BYTES: 12,
  UINT32: 13,
  ENUM: 14,
  SFIXED32: 15,
  SFIXED64: 16,
  SINT32: 17,
  SINT64: 18,
});

const _LABEL_REPEATED = 3;
const _JS_STRING = 1;

/**
 * The name of the jspb accessors of a field, without their prefix and suffix, like JSIdent() of protoc-gen-js.
 * @param {string} name The name of the field in the .proto file.
 * @returns {string} e.g. 'Shoulder0Offset' for 'shoulder_0_offset'.
 */
function _jsIdent(name) {
  return name
    .split('_')
    .filter(Boolean)
    .map(word => word.toLowerCase())
    .map(word => (word[0] >= 'a' && word[0] <= 'z' ? word[0].toUpperCase() + word.slice(1) : word))
    .join('');
}

/**
 * The name of a field in the JSON format, like _ToJsonName() of Python (protoc sets the same in the descriptors).
 * @param {string} name The name of the field in the .proto file.
 * @returns {string} e.g. 'shoulder0Offset' for 'shoulder_0_offset'.
 */
function _toJsonName(name) {
  let capitalizeNext = false;
  let result = '';
  for (const char of name) {
    if (char === '_') {
      capitalizeNext = true;
    } else if (capitalizeNext) {
      result += char.toUpperCase();
      capitalizeNext = false;
    } else {
      result += char;
    }
  }
  return result;
}

/**
 * The name of an accessor, with the '$' that protoc-gen-js adds to the ones of jspb.Message.
 * @param {string} name
 * @returns {string}
 */
function _jsName(name) {
  return name === 'Extension' || name === 'JsPbMessageId' ? `${name}$` : name;
}

/** Descriptor of an enum. */
class EnumDescriptor {
  constructor(fullName, proto, file) {
    this.fullName = fullName;
    this.name = proto.getName();
    this.file = file;
    this.values = proto.getValueList().map(value => ({ name: value.getName(), number: value.getNumber() }));
    this.valuesByName = new Map(this.values.map(value => [value.name, value]));
    // The first value of a number, like upb for the aliases.
    this.valuesByNumber = new Map();
    for (const value of this.values) {
      if (!this.valuesByNumber.has(value.number)) this.valuesByNumber.set(value.number, value);
    }
    // The enums of proto3 are open: any number is a value.
    this.isClosed = file.syntax !== 'proto3' && file.syntax !== 'editions';
  }
}

/** Descriptor of a field of a message. */
class FieldDescriptor {
  constructor(pool, proto, index, containingType) {
    this._pool = pool;
    this.name = proto.getName();
    this.fullName = `${containingType.fullName}.${this.name}`;
    // The name in the JSON format: lowerCamelCase, unless the .proto file sets json_name.
    this.jsonName = proto.getJsonName() || _toJsonName(this.name);
    this.number = proto.getNumber();
    this.index = index;
    this.type = proto.getType();
    this.isRepeated = proto.getLabel() === _LABEL_REPEATED;
    this.typeName = proto.getTypeName().replace(/^\./, '');
    this.containingType = containingType;
    // The oneof of the field, null for the synthetic ones of the proto3 optional fields.
    this.containingOneof =
      proto.hasOneofIndex() && !proto.getProto3Optional() ? containingType.oneofs[proto.getOneofIndex()] : null;
    this.isMessage = this.type === FieldType.MESSAGE || this.type === FieldType.GROUP;
    this.hasPresence =
      !this.isRepeated && (this.isMessage || proto.hasOneofIndex() || containingType.file.syntax !== 'proto3');
    // A 64 bits integer given as a string by jspb ([jstype = JS_STRING]).
    this.isJsString = proto.getOptions()?.getJstype() === _JS_STRING;
    this._messageType = undefined;
    this._enumType = undefined;
    this._accessors = null;
  }

  /** @returns {?Descriptor} The type of a message field. */
  get messageType() {
    if (this._messageType === undefined) {
      this._messageType = this.isMessage ? this._pool.findMessageTypeByName(this.typeName) : null;
    }
    return this._messageType;
  }

  /** @returns {?EnumDescriptor} The type of an enum field. */
  get enumType() {
    if (this._enumType === undefined) {
      this._enumType = this.type === FieldType.ENUM ? this._pool.findEnumTypeByName(this.typeName) : null;
    }
    return this._enumType;
  }

  /** @returns {boolean} Whether the field is a map. */
  get isMap() {
    return this.isRepeated && this.type === FieldType.MESSAGE && Boolean(this.messageType?.isMapEntry);
  }

  /**
   * The names of the jspb accessors of the field: get (the getter, of the list or the map for a repeated field),
   * getU8 (the getter of the bytes as Uint8Array), set, add (for a repeated field), has and clear.
   * @returns {{get: string, getU8: string, set: string, add: string, has: string, clear: string}}
   */
  get accessors() {
    if (this._accessors === null) {
      const ident = _jsIdent(this.name);
      const suffix = this.isMap ? 'Map' : this.isRepeated ? 'List' : '';
      this._accessors = {
        get: `get${_jsName(ident + suffix)}`,
        getU8: `get${ident}${suffix}_asU8`,
        set: `set${_jsName(ident + suffix)}`,
        add: `add${_jsName(ident)}`,
        has: `has${_jsName(ident + suffix)}`,
        clear: `clear${_jsName(ident + suffix)}`,
      };
    }
    return this._accessors;
  }
}

/** Descriptor of a message. */
class Descriptor {
  constructor(pool, fullName, proto, file, containingType) {
    this.fullName = fullName;
    this.name = proto.getName();
    this.file = file;
    this.containingType = containingType;
    this.isMapEntry = Boolean(proto.getOptions()?.getMapEntry());
    this.isExtendable = proto.getExtensionRangeList().length > 0;
    this.oneofs = proto.getOneofDeclList().map((oneof, index) => ({ name: oneof.getName(), index, fields: [] }));
    this.fields = proto.getFieldList().map((field, index) => new FieldDescriptor(pool, field, index, this));
    for (const field of this.fields) field.containingOneof?.fields.push(field);
    this.fieldsByName = new Map(this.fields.map(field => [field.name, field]));
    this.fieldsByNumber = new Map(this.fields.map(field => [field.number, field]));
    // The order of ListFields() in Python.
    this.fieldsInNumberOrder = [...this.fields].sort((a, b) => a.number - b.number);
  }
}

/**
 * The generated class of a message type if its module is loaded.
 * @param {string} fullName
 * @returns {?Function}
 */
function _loadedClass(fullName) {
  let node = globalThis.proto;
  for (const part of fullName.split('.')) {
    if (!node || !Object.hasOwn(node, part)) return null;
    node = node[part];
  }
  return typeof node === 'function' ? node : null;
}

/**
 * The module generated by protoc-gen-js for a .proto file.
 * @param {string} fileName e.g. 'bosdyn/api/geometry.proto'.
 * @returns {string}
 */
function _moduleOf(fileName) {
  const moduleName = fileName.replace(/\.proto$/, '_pb.js');
  // The well known types are generated in the google-protobuf package.
  return fileName.startsWith('google/protobuf/')
    ? `google-protobuf/${moduleName}`
    : path.join(__dirname, '..', moduleName);
}

/** The descriptors of a FileDescriptorSet, indexed by full name. */
class DescriptorPool {
  /**
   * @param {Uint8Array} serializedFileDescriptorSet
   */
  constructor(serializedFileDescriptorSet) {
    const { FileDescriptorSet } = require('google-protobuf/google/protobuf/descriptor_pb.js');
    const fileDescriptorSet = FileDescriptorSet.deserializeBinary(serializedFileDescriptorSet);

    /** @type {Map<string, Descriptor>} */
    this._messages = new Map();
    /** @type {Map<string, EnumDescriptor>} */
    this._enums = new Map();
    this._classToDescriptor = new WeakMap();

    for (const fileProto of fileDescriptorSet.getFileList()) {
      const file = { name: fileProto.getName(), package: fileProto.getPackage(), syntax: fileProto.getSyntax() };
      if (!file.syntax) file.syntax = 'proto2';
      const addEnum = (proto, scope) => {
        const fullName = `${scope}${proto.getName()}`;
        this._enums.set(fullName, new EnumDescriptor(fullName, proto, file));
      };
      const addMessage = (proto, scope, containingType) => {
        const descriptor = new Descriptor(this, `${scope}${proto.getName()}`, proto, file, containingType);
        this._messages.set(descriptor.fullName, descriptor);
        for (const enumProto of proto.getEnumTypeList()) addEnum(enumProto, `${descriptor.fullName}.`);
        for (const nested of proto.getNestedTypeList()) addMessage(nested, `${descriptor.fullName}.`, descriptor);
      };
      const scope = file.package ? `${file.package}.` : '';
      for (const enumProto of fileProto.getEnumTypeList()) addEnum(enumProto, scope);
      for (const messageProto of fileProto.getMessageTypeList()) addMessage(messageProto, scope, null);
    }
  }

  /** @returns {IterableIterator<Descriptor>} */
  messageTypes() {
    return this._messages.values();
  }

  /**
   * @param {string} fullName e.g. 'bosdyn.api.SE3Pose'.
   * @returns {?Descriptor}
   */
  findMessageTypeByName(fullName) {
    return this._messages.get(fullName) ?? null;
  }

  /**
   * @param {string} fullName
   * @returns {?EnumDescriptor}
   */
  findEnumTypeByName(fullName) {
    return this._enums.get(fullName) ?? null;
  }

  /**
   * The generated class of a message type, whose module is loaded if it was not.
   * @param {Descriptor} descriptor
   * @returns {Function}
   */
  messageClass(descriptor) {
    if (descriptor.isMapEntry) {
      throw new TypeError(`${descriptor.fullName} is a map entry: it has no class`);
    }
    let cls = _loadedClass(descriptor.fullName);
    if (cls === null) {
      require(_moduleOf(descriptor.file.name));
      cls = _loadedClass(descriptor.fullName);
    }
    if (cls === null) {
      throw new Error(`No generated class for ${descriptor.fullName} in ${_moduleOf(descriptor.file.name)}`);
    }
    this._classToDescriptor.set(cls, descriptor);
    return cls;
  }

  /**
   * The descriptor of a message of a generated class.
   * @param {import('google-protobuf').Message} message
   * @returns {Descriptor}
   * @throws {TypeError} The message is not of a class of the descriptor set.
   */
  descriptorOf(message) {
    const cls = message?.constructor;
    let descriptor = cls ? this._classToDescriptor.get(cls) : undefined;
    if (descriptor === undefined && typeof cls === 'function') {
      // The classes of the modules loaded since the last search.
      for (const candidate of this._messages.values()) {
        if (candidate.isMapEntry) continue;
        const loaded = _loadedClass(candidate.fullName);
        if (loaded !== null) this._classToDescriptor.set(loaded, candidate);
      }
      descriptor = this._classToDescriptor.get(cls);
    }
    if (descriptor === undefined) {
      throw new TypeError(`Not a protobuf message of the SDK: ${cls?.name ?? typeof message}`);
    }
    return descriptor;
  }
}

let _defaultPool = null;

/**
 * The pool of the descriptors of the SDK (loaded at the first call).
 * @returns {DescriptorPool}
 */
function defaultPool() {
  if (_defaultPool === null) {
    _defaultPool = new DescriptorPool(readFileSync(DESCRIPTOR_SET_PATH));
  }
  return _defaultPool;
}

/**
 * Whether the value of a singular field without presence (proto3) is its default: such a field is only merged when
 * it is not, like Python.
 * @param {FieldDescriptor} field
 * @param {*} value
 * @returns {boolean}
 */
function _isDefaultValue(field, value) {
  if (field.type === FieldType.BYTES) return value.length === 0;
  if (field.isJsString) return value === '0' || value === '';
  return value === 0 || value === '' || value === false;
}

/**
 * Merge a message into another one of the same type, like MergeFrom() in Python: the singular fields set in the source
 * overwrite the ones of the target (the sub-messages are merged recursively, and a oneof member replaces the others),
 * the repeated fields are appended, and the map entries replace the ones with the same key. jspb has no merge (parsing
 * concatenated messages replaces the sub-messages). The source is not modified, and shares nothing with the target.
 * @param {import('google-protobuf').Message} target
 * @param {import('google-protobuf').Message} source
 * @param {DescriptorPool} [pool=defaultPool()]
 * @returns {import('google-protobuf').Message} The target.
 * @throws {TypeError} The messages are not of the same type.
 */
function mergeFrom(target, source, pool = defaultPool()) {
  if (!source || target?.constructor !== source.constructor) {
    throw new TypeError('Parameter to MergeFrom() must be instance of same class.');
  }
  const descriptor = pool.descriptorOf(source);
  for (const field of descriptor.fields) {
    const { get, getU8, set, has } = field.accessors;
    const bytes = field.type === FieldType.BYTES;
    if (field.isMap) {
      const valueIsMessage = field.messageType.fieldsByName.get('value').isMessage;
      const targetMap = target[get]();
      source[get]().forEach((value, key) => targetMap.set(key, valueIsMessage ? value.clone() : value));
    } else if (field.isRepeated) {
      const values = bytes ? source[getU8]() : source[get]();
      if (values.length === 0) continue;
      const copies = field.isMessage ? values.map(value => value.clone()) : values.map(value => value);
      target[set]([...(bytes ? target[getU8]() : target[get]()), ...copies]);
    } else if (field.isMessage) {
      if (!source[has]()) continue;
      if (target[has]()) {
        mergeFrom(target[get](), source[get](), pool);
      } else {
        target[set](source[get]().clone());
      }
    } else {
      const value = bytes ? source[getU8]() : source[get]();
      if (field.hasPresence ? !source[has]() : _isDefaultValue(field, value)) continue;
      target[set](bytes ? Uint8Array.from(value) : value);
    }
  }
  return target;
}

module.exports = {
  DESCRIPTOR_SET_PATH,
  Descriptor,
  DescriptorPool,
  EnumDescriptor,
  FieldDescriptor,
  FieldType,
  defaultPool,
  mergeFrom,
};
